SimulationExperiment.AfterSimulationRunCode:
double elapsedHours = Math.max(
    1e-9,
    (root.time() - root.alStartTime) / 3600.0
);

String scenarioName =
    root.alRushMode ? "rush" : "steady";

int unfinishedTasks =
    root.alTaskCount - root.alThroughput;

double uph =
    root.alThroughput / elapsedHours;

double avgCycleTimeMin =
    root.alThroughput > 0
    ? root.alCycleTimeSumSec
        / root.alThroughput / 60.0
    : 0.0;

double avgWaitingTimeMin =
    root.alThroughput > 0
    ? root.alWaitingTimeSumSec
        / root.alThroughput / 60.0
    : 0.0;

double agvUtilizationPct =
    100.0 * root.AGVFleet.utilization();

traceln("========== 最终统计 ==========");
traceln("Scenario = " + scenarioName);
traceln("Run seed = " + root.alRunSeed);
traceln("Generated tasks = " + root.alTaskCount);
traceln("Completed tasks = " + root.alThroughput);
traceln("Unfinished tasks = " + unfinishedTasks);
traceln("UPH = " + uph);
traceln("Average cycle time (min) = " + avgCycleTimeMin);
traceln("Average waiting time (min) = " + avgWaitingTimeMin);
traceln("Maximum WIP = " + root.alMaxWIP);
traceln("AGV utilization (%) = " + agvUtilizationPct);
traceln("Elapsed hours = " + elapsedHours);

try {
    String csvPath = "anylogic_validation_results.csv";

    java.io.File csvFile =
        new java.io.File(csvPath);

    boolean writeHeader =
        !csvFile.exists() || csvFile.length() == 0;

    java.io.BufferedWriter writer =
        new java.io.BufferedWriter(
            new java.io.FileWriter(csvFile, true)
        );


    if (writeHeader) {
        writer.write(
            "scenario,seed,horizon_h,generated_tasks,"
            + "completed_tasks,unfinished_tasks,uph,"
            + "avg_cycle_time_min,avg_waiting_time_min,"
            + "max_wip,agv_utilization_pct"
        );
        writer.newLine();
    }

    writer.write(
        scenarioName + ","
        + root.alRunSeed + ","
        + elapsedHours + ","
        + root.alTaskCount + ","
        + root.alThroughput + ","
        + unfinishedTasks + ","
        + uph + ","
        + avgCycleTimeMin + ","
        + avgWaitingTimeMin + ","
        + root.alMaxWIP + ","
        + agvUtilizationPct
    );

    writer.newLine();
    writer.close();

    traceln("CSV saved to: " + csvPath);

} catch (Exception e) {
    traceln("CSV write failed: " + e.getMessage());
}
